 h,w=len(g),len(g[0]); out=[[0]*w for _ in range(h)]
 for r in range(h):
  xs=[c for c in range(w) if g[r][c]]
  if xs:
   for c in range(min(xs),max(xs)+1): out[r][c]=9
 for c in range(w):
  ys=[r for r in range(h) if g[r][c]]
  if ys:
   for r in range(min(ys),max(ys)+1): out[r][c]=9
 return out"},{"nl":"Turn all 2 cells into 9 and flood-fill the orthogonally enclosed/connected region toward the nearest edges.","code":"def transform(g):
