 h,w=len(g),len(g[0]); out=[[0]*w for _ in range(h)]
 for r in range(h):
  q=[c for c,x in enumerate(g[r]) if x]
  if q:
   for c in range(min(q),max(q)+1): out[r][c]=9
 return out"},{"nl":"Expand the nonzero motif by repeatedly completing rows and columns until it forms the maximal orthogonally convex 9-shape.","code":"def transform(g):
