  changed=False
  for r in range(h):
   q=[c for c in range(w) if out[r][c]]
   if q:
    for c in range(min(q),max(q)+1):
     if not out[r][c]: out[r][c]=9;changed=True
  for c in range(w):
   q=[r for r in range(h) if out[r][c]]
   if q:
    for r in range(min(q),max(q)+1):
     if not out[r][c]:out[r][c]=9;changed=True
 return out"}]}

